SELECT COUNT(DISTINCT f.customer_id), COUNT(DISTINCT o.customer_id) FROM (SELECT customer_id FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') GROUP BY customer_id HAVING MIN(order_at) >= TIMESTAMP '2025-04-01' AND MIN(order_at) < TIMESTAMP '2025-06-30' + INTERVAL 1 DAY) f LEFT JOIN orders o ON o.customer_id = f.customer_id AND o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2025-07-01 00:00:00' AND o.order_at < TIMESTAMP '2025-10-01 00:00:00'
